#include <list>
#include <unordered_map>
#include <shared_mutex>
#include <optional>
#include <cstddef>

template <typename K, typename V>
class LRUCache {
private:
    using Node = std::pair<K, V>;
    using List = std::list<Node>;
    using ListIter = typename List::iterator;

    List order_;
    std::unordered_map<K, ListIter> cache_;
    const std::size_t capacity_;
    mutable std::shared_mutex mtx_;

    void promote(ListIter it) {
        order_.splice(order_.begin(), order_, it);
    }

public:
    explicit LRUCache(std::size_t capacity) : capacity_(capacity) {}

    std::optional<V> get(const K& key) {
        std::unique_lock<std::shared_mutex> lock(mtx_);
        auto map_it = cache_.find(key);
        if (map_it == cache_.end()) {
            return std::nullopt;
        }
        promote(map_it->second);
        return map_it->second->second;
    }

    void put(const K& key, const V& value) {
        std::unique_lock<std::shared_mutex> lock(mtx_);
        auto map_it = cache_.find(key);
        if (map_it != cache_.end()) {
            map_it->second->second = value;
            promote(map_it->second);
        } else {
            if (order_.size() == capacity_) {
                auto back = order_.back();
                order_.pop_back();
                cache_.erase(back.first);
            }
            order_.emplace_front(key, value);
            cache_[key] = order_.begin();
        }
    }

    std::size_t size() const {
        std::shared_lock<std::shared_mutex> lock(mtx_);
        return order_.size();
    }
};
