class Matrix {
    double* data_;
    int rows_;
    int cols_;

public:
    Matrix(int rows, int cols) : data_(nullptr), rows_(rows), cols_(cols) {
        if (rows <= 0 || cols <= 0) {
            throw std::invalid_argument("Rows and columns must be positive.");
        }
        data_ = new double[rows_ * cols_];
        std::fill(data_, data_ + rows_ * cols_, 0.0);
    }

    ~Matrix() {
        delete[] data_;
    }

    Matrix(const Matrix& other) : data_(nullptr), rows_(other.rows_), cols_(other.cols_) {
        data_ = new double[rows_ * cols_];
        std::copy(other.data_, other.data_ + rows_ * cols_, data_);
    }

    Matrix& operator=(const Matrix& other) {
        if (this != &other) {
            delete[] data_;
            rows_ = other.rows_;
            cols_ = other.cols_;
            data_ = new double[rows_ * cols_];
            std::copy(other.data_, other.data_ + rows_ * cols_, data_);
        }
        return *this;
    }

    Matrix(Matrix&& other) noexcept : data_(other.data_), rows_(other.rows_), cols_(other.cols_) {
        other.data_ = nullptr;
        other.rows_ = 0;
        other.cols_ = 0;
    }

    Matrix& operator=(Matrix&& other) noexcept {
        if (this != &other) {
            delete[] data_;
            data_ = other.data_;
            rows_ = other.rows_;
            cols_ = other.cols_;
            other.data_ = nullptr;
            other.rows_ = 0;
            other.cols_ = 0;
        }
        return *this;
    }

    double& at(int r, int c) {
        if (r < 0 || r >= rows_ || c < 0 || c >= cols_) {
            throw std::out_of_range("Index out of bounds");
        }
        return data_[r * cols_ + c];
    }

    double at(int r, int c) const {
        if (r < 0 || r >= rows_ || c < 0 || c >= cols_) {
            throw std::out_of_range("Index out of bounds");
        }
        return data_[r * cols_ + c];
    }

    int rows() const { return rows_; }
    int cols() const { return cols_; }

    Matrix operator+(const Matrix& o) const {
        if (rows_ != o.rows_ || cols_ != o.cols_) {
            throw std::invalid_argument("Matrix dimensions must match for addition.");
        }
        Matrix result(rows_, cols_);
        for (int i = 0; i < rows_ * cols_; ++i) {
            result.data_[i] = data_[i] + o.data_[i];
